// ---- signature.mjs
// Meta signs each POST body with HMAC-SHA256 using the app secret (header X-Hub-Signature-256: sha256=<hex>).
// The GET handshake echoes hub.challenge when hub.verify_token matches.
// SHA-256 is written out here, with no imports, so the same code runs in an n8n Code node without
// NODE_FUNCTION_ALLOW_BUILTIN and in the browser. The tests check it against Node's crypto module.

const K = new Uint32Array([0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d,
  0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2]);

const toBytes = x => (x instanceof Uint8Array ? x : new TextEncoder().encode(String(x)));

function sha256(input) {
  const msg = toBytes(input), len = msg.length;
  const padded = new Uint8Array(((len + 9 + 63) >> 6) << 6);
  padded.set(msg); padded[len] = 0x80;
  const dv = new DataView(padded.buffer);
  dv.setUint32(padded.length - 8, Math.floor(len / 0x20000000)); dv.setUint32(padded.length - 4, (len << 3) >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h[0] += a; h[1] += b; h[2] += c; h[3] += d; h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
  }
  const out = new Uint8Array(32); const ov = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) ov.setUint32(i * 4, h[i]);
  return out;
}

function hmacSha256Hex(key, message) {
  let k = toBytes(key);
  if (k.length > 64) k = sha256(k);
  const ipad = new Uint8Array(64 + toBytes(message).length), opad = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) { ipad[i] = (k[i] ?? 0) ^ 0x36; opad[i] = (k[i] ?? 0) ^ 0x5c; }
  ipad.set(toBytes(message), 64);
  opad.set(sha256(ipad), 64);
  return [...sha256(opad)].map(b => b.toString(16).padStart(2, '0')).join('');
}

// rawBody must be the exact bytes Meta sent. Re-serialising parsed JSON changes them (Meta escapes Arabic as \uXXXX).
function verifySignature(rawBody, header, appSecret) {
  if (!header || !appSecret || !String(header).startsWith('sha256=')) return false;
  const got = String(header).slice(7).toLowerCase(), expected = hmacSha256Hex(appSecret, rawBody);
  if (got.length !== expected.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= got.charCodeAt(i) ^ expected.charCodeAt(i); // same time whatever the mismatch position
  return diff === 0;
}

function verifyChallenge(query, verifyToken) {
  if (query?.['hub.mode'] === 'subscribe' && verifyToken && query?.['hub.verify_token'] === verifyToken) return { status: 200, body: String(query['hub.challenge'] ?? '') };
  return { status: 403, body: 'Forbidden' };
}

const cfg = k => { try { if (typeof $vars !== 'undefined' && $vars[k] != null && $vars[k] !== '') return $vars[k]; } catch (e) {}
  try { return $env[k]; } catch (e) { return undefined; } };
const need = k => { const v = cfg(k); if (v == null || v === '') throw new Error(k + ' is not set: add it under Variables or as an environment variable'); return v; };
const q = $input.first().json.query || {};
return [{ json: verifyChallenge(q, need('WA_VERIFY_TOKEN')) }];

// ---- whatsapp.mjs
// WhatsApp Cloud API: reading webhooks and building send payloads, with the platform's limits enforced in code.
const LIMITS = { textBody: 4096, interactiveBody: 1024, buttons: 3, buttonTitle: 20, listRows: 10, rowTitle: 24, rowDescription: 72, listButton: 20, windowMs: 24 * 3600 * 1000 };

// One webhook POST can carry several messages and status updates. Only customer messages get an answer.
function parseWebhook(body) {
  const out = [];
  if (!body || body.object !== 'whatsapp_business_account') return out;
  for (const entry of body.entry ?? []) for (const change of entry.changes ?? []) {
    if (change.field !== 'messages') continue;
    const v = change.value ?? {};
    const phoneNumberId = v.metadata?.phone_number_id ?? null;
    const names = Object.fromEntries((v.contacts ?? []).map(c => [c.wa_id, c.profile?.name ?? null]));
    for (const m of v.messages ?? []) {
      const base = { kind: 'message', id: m.id, from: m.from, name: names[m.from] ?? null, timestampMs: Number(m.timestamp) * 1000, phoneNumberId, type: m.type };
      if (m.type === 'text') out.push({ ...base, text: m.text?.body ?? '' });
      else if (m.type === 'interactive') { const r = m.interactive?.button_reply ?? m.interactive?.list_reply ?? {}; out.push({ ...base, replyId: r.id ?? null, text: r.title ?? '' }); }
      else if (m.type === 'button') out.push({ ...base, replyId: m.button?.payload ?? null, text: m.button?.text ?? '' });
      else out.push({ ...base, unsupported: true, text: '' });
    }
    for (const s of v.statuses ?? []) out.push({ kind: 'status', id: s.id, status: s.status, recipient: s.recipient_id, phoneNumberId });
  }
  return out;
}

// Meta retries a notification until it gets a 200, and retries go to every subscribed app, so the same message can arrive twice.
// The store is a plain object so n8n can keep it in workflow static data between executions.
function seenBefore(store, id, nowMs, ttlMs = 3 * 24 * 3600 * 1000) {
  for (const [k, t] of Object.entries(store)) if (nowMs - t > ttlMs) delete store[k];
  if (Object.prototype.hasOwnProperty.call(store, id)) return true;
  store[id] = nowMs;
  return false;
}

const windowOpen = (lastInboundMs, atMs) => lastInboundMs != null && atMs - lastInboundMs < LIMITS.windowMs;

// A day-before reminder can go as a normal message only if the customer wrote within the 24 hours before it.
// Bookings less than a day away get no day-before reminder; one to two days away, a normal message; further ahead, a template.
function reminderPlan(appointmentMs, lastInboundMs, nowMs, leadMs = 24 * 3600 * 1000) {
  const sendAtMs = appointmentMs - leadMs;
  if (sendAtMs <= nowMs) return { sendAtMs: null, kind: 'none' };
  return { sendAtMs, kind: windowOpen(lastInboundMs, sendAtMs) ? 'service' : 'template' };
}

function splitText(body, max = LIMITS.textBody) {
  const parts = []; let rest = String(body);
  while (rest.length > max) {
    let cut = Math.max(rest.lastIndexOf('\n', max), rest.lastIndexOf('. ', max) + 1, rest.lastIndexOf(' ', max));
    if (cut <= 0) cut = max;
    parts.push(rest.slice(0, cut).trimEnd()); rest = rest.slice(cut).trimStart();
  }
  if (rest) parts.push(rest);
  return parts;
}

const base = to => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const textPayloads = (to, body) => splitText(body).map(t => ({ ...base(to), type: 'text', text: { preview_url: false, body: t } }));

function buttonsPayload(to, body, buttons, footer) {
  if (!buttons.length || buttons.length > LIMITS.buttons) throw new Error(`reply buttons: 1 to ${LIMITS.buttons}, got ${buttons.length}`);
  if (body.length > LIMITS.interactiveBody) throw new Error('interactive body over 1024 characters');
  const titles = new Set();
  for (const b of buttons) {
    if (!b.title || b.title.length > LIMITS.buttonTitle) throw new Error(`button title "${b.title}" must be 1-${LIMITS.buttonTitle} characters`);
    if (titles.has(b.title)) throw new Error('button titles must be unique'); titles.add(b.title);
    if (!b.id || b.id.length > 256 || b.id !== b.id.trim()) throw new Error('button id must be 1-256 characters with no outer spaces');
  }
  return { ...base(to), type: 'interactive', interactive: { type: 'button', body: { text: body }, ...(footer ? { footer: { text: footer } } : {}),
    action: { buttons: buttons.map(b => ({ type: 'reply', reply: { id: b.id, title: b.title } })) } } };
}

function listPayload(to, body, buttonText, rows, sectionTitle) {
  if (!rows.length || rows.length > LIMITS.listRows) throw new Error(`list rows: 1 to ${LIMITS.listRows}`);
  if (buttonText.length > LIMITS.listButton) throw new Error('list button text over 20 characters');
  for (const r of rows) if (r.title.length > LIMITS.rowTitle || (r.description ?? '').length > LIMITS.rowDescription) throw new Error(`list row "${r.title}" too long`);
  return { ...base(to), type: 'interactive', interactive: { type: 'list', body: { text: body }, action: { button: buttonText, sections: [{ title: sectionTitle.slice(0, 24), rows }] } } };
}

const templatePayload = (to, name, languageCode, params) => ({ ...base(to), type: 'template',
  template: { name, language: { code: languageCode }, components: [{ type: 'body', parameters: params.map(text => ({ type: 'text', text: String(text) })) }] } });

// ---- signature.mjs
// Meta signs each POST body with HMAC-SHA256 using the app secret (header X-Hub-Signature-256: sha256=<hex>).
// The GET handshake echoes hub.challenge when hub.verify_token matches.
// SHA-256 is written out here, with no imports, so the same code runs in an n8n Code node without
// NODE_FUNCTION_ALLOW_BUILTIN and in the browser. The tests check it against Node's crypto module.

const K = new Uint32Array([0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d,
  0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2]);

const toBytes = x => (x instanceof Uint8Array ? x : new TextEncoder().encode(String(x)));

function sha256(input) {
  const msg = toBytes(input), len = msg.length;
  const padded = new Uint8Array(((len + 9 + 63) >> 6) << 6);
  padded.set(msg); padded[len] = 0x80;
  const dv = new DataView(padded.buffer);
  dv.setUint32(padded.length - 8, Math.floor(len / 0x20000000)); dv.setUint32(padded.length - 4, (len << 3) >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h[0] += a; h[1] += b; h[2] += c; h[3] += d; h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
  }
  const out = new Uint8Array(32); const ov = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) ov.setUint32(i * 4, h[i]);
  return out;
}

function hmacSha256Hex(key, message) {
  let k = toBytes(key);
  if (k.length > 64) k = sha256(k);
  const ipad = new Uint8Array(64 + toBytes(message).length), opad = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) { ipad[i] = (k[i] ?? 0) ^ 0x36; opad[i] = (k[i] ?? 0) ^ 0x5c; }
  ipad.set(toBytes(message), 64);
  opad.set(sha256(ipad), 64);
  return [...sha256(opad)].map(b => b.toString(16).padStart(2, '0')).join('');
}

// rawBody must be the exact bytes Meta sent. Re-serialising parsed JSON changes them (Meta escapes Arabic as \uXXXX).
function verifySignature(rawBody, header, appSecret) {
  if (!header || !appSecret || !String(header).startsWith('sha256=')) return false;
  const got = String(header).slice(7).toLowerCase(), expected = hmacSha256Hex(appSecret, rawBody);
  if (got.length !== expected.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= got.charCodeAt(i) ^ expected.charCodeAt(i); // same time whatever the mismatch position
  return diff === 0;
}

function verifyChallenge(query, verifyToken) {
  if (query?.['hub.mode'] === 'subscribe' && verifyToken && query?.['hub.verify_token'] === verifyToken) return { status: 200, body: String(query['hub.challenge'] ?? '') };
  return { status: 403, body: 'Forbidden' };
}

const item = $input.first();
const cfg = k => { try { if (typeof $vars !== 'undefined' && $vars[k] != null && $vars[k] !== '') return $vars[k]; } catch (e) {}
  try { return $env[k]; } catch (e) { return undefined; } };
const need = k => { const v = cfg(k); if (v == null || v === '') throw new Error(k + ' is not set: add it under Variables or as an environment variable'); return v; };
let raw;
try { raw = await this.helpers.getBinaryDataBuffer(0, 'data'); }
catch (e) { throw new Error('No raw body: turn on "Raw Body" in the WhatsApp events (POST) node options. The signature is over the exact bytes Meta sent.'); }
const headers = item.json.headers || {};
if (!verifySignature(new Uint8Array(raw), headers['x-hub-signature-256'], need('WA_APP_SECRET'))) return []; // not from Meta: drop it
let body;
try { body = JSON.parse(raw.toString('utf8')); } catch (e) { return []; }
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = cfg('CLOCK_OVERRIDE_MS') ? Number(cfg('CLOCK_OVERRIDE_MS')) : Date.now(); // the override is for testing only
const out = [];
for (const ev of parseWebhook(body)) {
  if (ev.kind !== 'message') continue;              // sent / delivered / read receipts never get a reply
  if (seenBefore(store.seen, ev.id, now)) continue;  // Meta retries can deliver the same message twice
  out.push({ json: ev });
}
return out;

// ---- normalize.mjs
// Arabic text the way customers type it: with or without hamza, taa marbuta, diacritics, tatweel, Arabic-Indic digits.
// Everything is matched after this, so "بكرة", "بكره" and "بُكرة" are the same word.
const DIGITS = { '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4', '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
  '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4', '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9' };
function westernDigits(s) { return String(s ?? '').replace(/[٠-٩۰-۹]/g, d => DIGITS[d]); }

function normalizeText(s) {
  return westernDigits(s)
    .replace(/[ً-ْٰ]/g, '')        // diacritics (tashkeel)
    .replace(/ـ/g, '')                       // tatweel
    .replace(/[أإآٱ]/g, 'ا') // alef forms -> bare alef
    .replace(/ى/g, 'ي')                 // alef maqsura -> yaa
    .replace(/ة/g, 'ه')                 // taa marbuta -> haa
    .replace(/ؤ/g, 'و')                 // waw with hamza -> waw
    .replace(/ئ/g, 'ي')                 // yaa with hamza -> yaa
    .replace(/چ/g, 'ج')                 // Gulf "ch" (چ) -> jeem, so باچر = باجر
    .replace(/ک/g, 'ك').replace(/ی/g, 'ي') // Persian kaf / yeh keyboards
    .toLowerCase()
    .replace(/[؟،؛?!.,;:()"'«»“”‘’*_~]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
// The same matching without normalization, for measuring what normalization buys.
function plainText(s) { return String(s ?? '').toLowerCase().replace(/[?!.,;:()]/g, ' ').replace(/\s+/g, ' ').trim(); }

// ---- lang.mjs
// Which language to answer in. Arabic script -> Arabic. Latin script with Gulf "Arabizi" (3 = ع, 7 = ح, ...) -> Arabic too.


const ARABIZI_WORDS = new Set(['shlonk', 'shlonich', 'shlonech', 'kam', 'bkam', 'b kam', 'se3r', 'si3r', 's3r', 'asa3ar', 'as3ar', 'wain', 'wen', 'wainkom', 'mata', 'ab8a', 'abgha', 'abga', 'aby', 'abi', 'abee',
  'ba3d', 'b3d', 'bukra', 'bokra', 'bacher', 'bachir', 'baachir', 'inshallah', 'insha', 'hala', 'marhaba', 'mar7aba', '3ndkm', '3indkum', 'mumkin', 'momkin', 'mawa3eed', 'maw3ed', 'maw3id', '7ajz', '7jz', 'a7jz', 'a7joz',
  'salam', 'salaam', 'el', 'al', 'yalla', 'habibti', 'shukran', 'shokran', 'msh', 'mo', 'ma3', 'wayed', 'zain', 'zein', 'ya', 'akhti', 'ukhti', 'sabah', 'masa', 'el5air', 'alkhair', 'il7en', 'alhin', 'elhin', 'tftho', 'tftahon', 'tsakron', 'dawam']);
const DIGIT_LETTER = /^(?=.*[a-z])(?=.*[23456789])[a-z0-9']+$/; // words like 3ndkm, 7ajz, se3r

function detectLanguage(text) {
  const s = String(text ?? '');
  const arabic = (s.match(/[؀-ۿ]/g) ?? []).length;
  const latin = (s.match(/[A-Za-z]/g) ?? []).length;
  if (arabic >= 3 && arabic * 2 >= latin) return 'ar'; // a mostly-Arabic message with an English word or two
  if (!latin) return arabic ? 'ar' : 'en';
  const words = normalizeText(s).split(' ').filter(Boolean);
  const hits = words.filter(w => ARABIZI_WORDS.has(w) || (DIGIT_LETTER.test(w) && !/^\d+(am|pm)$/.test(w))).length;
  return hits >= 2 || (hits === 1 && words.length <= 3) ? 'ar' : 'en';
}

// ---- salon.mjs
// An invented sample salon in Doha. Names, prices, staff and hours are made up for the demo.
const SALON = {
  name: { en: 'Sample Salon, West Bay', ar: 'صالون تجريبي، الخليج الغربي' },
  currency: { en: 'QAR', ar: 'ر.ق' },
  // Day 0 = Sunday ... 6 = Saturday. Qatar's weekend is Friday and Saturday; this salon opens late on Friday.
  hours: { 0: [600, 1320], 1: [600, 1320], 2: [600, 1320], 3: [600, 1320], 4: [600, 1320], 5: [840, 1320], 6: [600, 1320] },
  address: { en: 'West Bay, Doha (sample address)', ar: 'الخليج الغربي، الدوحة (عنوان تجريبي)' },
  map: 'https://maps.google.com/?q=West+Bay+Doha',
  policies: { en: 'Ladies only. Card or cash. Please give 4 hours’ notice to change a booking.', ar: 'للسيدات فقط. الدفع بالبطاقة أو نقدًا. لتغيير الموعد نرجو إبلاغنا قبل 4 ساعات.' },
  services: [
    { id: 'haircut', en: 'Haircut and blow-dry', ar: 'قص وسشوار', price: 150, from: false, minutes: 60,
      words: ['haircut', 'hair cut', 'trim', 'cut my hair', 'قص', 'قصه', 'قص شعر', 'تشذيب', 'اقص'] },
    { id: 'blowdry', en: 'Blow-dry', ar: 'سشوار', price: 120, from: false, minutes: 45,
      words: ['blow dry', 'blowdry', 'blow-dry', 'blowout', 'سشوار', 'استشوار', 'سشوار'] },
    { id: 'colour', en: 'Hair colour', ar: 'صبغة', price: 350, from: true, minutes: 120,
