// ---- qatar.mjs
// Qatar time is UTC+3 all year (no daylight saving). Local times are handled as 'YYYY-MM-DDTHH:MM' strings.
const QATAR_OFFSET_MIN = 180;
const pad2 = n => String(n).padStart(2, '0');
function qatarParts(ms) {
  const d = new Date(ms + QATAR_OFFSET_MIN * 60000);
  return { date: `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`, dow: d.getUTCDay(), minutes: d.getUTCHours() * 60 + d.getUTCMinutes() };
}
function qatarMs(date, minutes) { return Date.parse(`${date}T00:00:00Z`) + (minutes - QATAR_OFFSET_MIN) * 60000; }
function addDaysISO(date, n) { const d = new Date(`${date}T00:00:00Z`); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function dowOf(date) { return new Date(`${date}T00:00:00Z`).getUTCDay(); }
const hhmm = m => `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
const localISO = (date, minutes) => `${date}T${hhmm(minutes)}`;
function parseLocal(iso) { const [date, t] = iso.split('T'); const [h, m] = t.split(':').map(Number); return { date, minutes: h * 60 + m }; }

// ---- understand.mjs
// What the customer wants, from rules that run before any AI call: intent, service, day and time.
// Prices, hours and slots then come from the salon's data, never from the model.




const N = s => normalizeText(s);
const PREFIXES = ['وال', 'بال', 'لل', 'ال', 'و', 'ب', 'ل', 'ف'];
const SUFFIXES = ['كم', 'كن', 'ها', 'نا', 'ي', 'ك'];
function variants(tok) {
  const out = new Set([tok]);
  for (const p of PREFIXES) if (tok.startsWith(p) && tok.length - p.length >= 2) out.add(tok.slice(p.length));
  for (const v of [...out]) for (const x of SUFFIXES) if (/[؀-ۿ]/.test(v) && v.endsWith(x) && v.length - x.length >= 3) out.add(v.slice(0, -x.length));
  return out;
}
// Phrase match on whole tokens, allowing Arabic prefixes (al-, wal-, bil-, li-, wa-, bi-) on the first token.
function findPhrase(tokens, phrase) {
  const p = phrase.split(' ');
  for (let i = 0; i + p.length <= tokens.length; i++) {
    if (!variants(tokens[i]).has(p[0])) continue;
    let ok = true;
    for (let j = 1; j < p.length; j++) if (!variants(tokens[i + j]).has(p[j])) { ok = false; break; }
    if (ok) return i;
  }
  return -1;
}
const has = (tokens, list) => list.some(w => findPhrase(tokens, w) >= 0);

const AR = s => N(s);
const KW = {
  human: ['human', 'real person', 'staff', 'agent', 'speak to someone', 'talk to someone', 'call me', 'manager', AR('موظفه'), AR('موظف'), AR('اكلم'), AR('اتصلوا'), AR('احد يرد'), AR('شخص'), AR('الاداره'), AR('الريسبشن')],
  cancel: ['cancel', 'reschedule', 'change my appointment', 'change my booking', 'move my appointment', AR('الغي'), AR('الغاء'), AR('اغير الموعد'), AR('تاجيل'), AR('غيري الموعد')],
  book: ['book', 'booking', 'appointment', 'reserve', 'reservation', 'slot', 'available', 'availability', 'can i come', 'free tomorrow', 'schedule', AR('احجز'), AR('حجز'), AR('موعد'), AR('ابي موعد'), AR('فاضي'), AR('فاضين'), AR('متاح'), AR('ابي اجي'), AR('اقدر اجي'), AR('ممكن اجي'), 'a7jz', '7ajz', 'maw3ed', 'maw3id'],
  price: ['price', 'prices', 'cost', 'how much', 'charge', 'rate', 'fees', 'menu', AR('سعر'), AR('اسعار'), AR('كم'), AR('بكم'), AR('تكلفه'), AR('يكلف'), AR('قايمه الاسعار'), 'kam', 'bkam', 'se3r', 'si3r', 'as3ar'],
  hours: ['open', 'opening', 'close', 'closing', 'hours', 'timing', 'timings', 'working time', AR('تفتحون'), AR('تسكرون'), AR('تقفلون'), AR('دوام'), AR('الدوام'), AR('دوامكم'), AR('اوقات'), AR('ساعات العمل'), AR('مفتوحين'), AR('مفتوح'), AR('فاتحين'), 'dawam', 'tftho', 'tftahon'],
  location: ['where', 'location', 'address', 'map', 'located', 'directions', AR('وين'), AR('موقع'), AR('عنوان'), AR('مكانكم'), AR('لوكيشن'), AR('الخريطه'), 'wain', 'wen', 'wainkom'],
  services: ['services', 'what do you offer', 'what do you do', 'treatments', AR('خدمات'), AR('الخدمات'), AR('شنو عندكم'), AR('وش عندكم')],
  thanks: ['thanks', 'thank you', 'thx', 'shukran', 'shokran', AR('شكرا'), AR('مشكوره'), AR('يعطيك العافيه'), AR('تسلمين'), AR('تسلمون')],
  greeting: ['hi', 'hello', 'hey', 'good morning', 'good evening', 'salam', 'hala', 'marhaba', AR('السلام عليكم'), AR('سلام'), AR('مرحبا'), AR('هلا'), AR('صباح الخير'), AR('مساء الخير')],
};
const SERVICE_WORDS = SALON.services.flatMap(s => s.words.map(w => [N(w), s.id])).sort((a, b) => b[0].length - a[0].length);

const DAYS_EN = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const DAYS_AR = ['الاحد', 'الاثنين', 'الثلاثاء', 'الاربعاء', 'الخميس', 'الجمعه', 'السبت'].map(N);
const TODAY = ['today', 'tonight', AR('اليوم'), AR('الحين'), 'alyom', 'el youm'];
const TOMORROW = ['tomorrow', 'tmrw', 'tmr', AR('بكره'), AR('باجر'), AR('بكرا'), 'bukra', 'bokra', 'bacher', 'bachir', 'baachir'];
const AFTER_TOMORROW = ['day after tomorrow', AR('بعد بكره'), AR('بعد باجر')];
const PM = ['pm', 'p.m', 'evening', 'afternoon', 'night', AR('م'), AR('مساء'), AR('المسا'), AR('العصر'), AR('بالليل'), AR('الليل'), AR('الظهر'), AR('المغرب'), AR('عصر'), AR('مسا')];
const AM = ['am', 'a.m', 'morning', AR('ص'), AR('صباحا'), AR('الصبح'), AR('الصباح'), AR('صبح')];
const HOUR_WORDS = { [N('وحده')]: 1, [N('واحده')]: 1, [N('ثنتين')]: 2, [N('اثنين')]: 2, [N('ثلاث')]: 3, [N('ثلاثه')]: 3,
  [N('اربع')]: 4, [N('اربعه')]: 4, [N('خمس')]: 5, [N('خمسه')]: 5, [N('ست')]: 6, [N('سته')]: 6, [N('سبع')]: 7, [N('سبعه')]: 7,
  [N('ثمان')]: 8, [N('ثمانيه')]: 8, [N('تسع')]: 9, [N('تسعه')]: 9, [N('عشر')]: 10, [N('عشره')]: 10, [N('حدعش')]: 11, [N('احدعش')]: 11, [N('ثنعش')]: 12, [N('اثنعش')]: 12 };
const AT = ['at', 'around', 'by', AR('الساعه'), AR('ساعه'), AR('الساعه'), 'alsa3a', 'el sa3a', 'sa3a'];

function extractDate(tokens, todayISO) {
  if (has(tokens, AFTER_TOMORROW)) return addDaysISO(todayISO, 2);
  if (has(tokens, TOMORROW)) return addDaysISO(todayISO, 1);
  if (has(tokens, TODAY)) return todayISO;
  for (let d = 0; d < 7; d++) {
    if (has(tokens, [DAYS_EN[d], DAYS_EN[d].slice(0, 3), DAYS_AR[d], DAYS_AR[d].replace(/^ال/, '')])) {
      const delta = (d - dowOf(todayISO) + 7) % 7;
      return addDaysISO(todayISO, delta);
    }
  }
  return null;
}

function extractTime(tokens) {
  for (let i = 0; i < tokens.length; i++) {
    let t = tokens[i], h = null, m = 0, mer = null;
    const glued = t.match(/^(\d{1,2})(?::(\d{2}))?(am|pm)$/);
    const plain = t.match(/^(\d{1,2})(?::(\d{2}))?$/);
    if (glued) { h = +glued[1]; m = +(glued[2] ?? 0); mer = glued[3]; }
    else if (plain) { h = +plain[1]; m = +(plain[2] ?? 0); }
    else if (HOUR_WORDS[t] && i > 0 && AT.some(a => variants(tokens[i - 1]).has(a.split(' ').at(-1)))) h = HOUR_WORDS[t];
    if (h === null || h > 23 || m > 59) continue;
    const next = tokens.slice(i + 1, i + 3).join(' '), prev = tokens[i - 1] ?? '';
    const nt = tokens[i + 1] ?? '';
    const said = list => list.some(w => (w.includes(' ') ? next.startsWith(w) : variants(nt).has(w)));
    if (!mer) { if (said(PM)) mer = 'pm'; else if (said(AM)) mer = 'am'; }
    const anchored = mer || AT.some(a => variants(prev).has(a.split(' ').at(-1))) || tokens[i - 1] === '@';
    if (!anchored) continue; // a bare number is probably a price, a count or a date
    if (mer === 'pm' && h < 12) h += 12;
    else if (mer === 'am' && h === 12) h = 0;
    else if (!mer && h >= 1 && h <= 9) h += 12; // "at 5" in a salon means 5 in the evening
    return h * 60 + m;
  }
  return null;
}

function understand(text, { todayISO, normalize = true } = {}) {
  const norm = normalize ? normalizeText(text) : plainText(text);
  const tokens = norm.split(' ').filter(Boolean);
  const service = (SERVICE_WORDS.find(([w]) => findPhrase(tokens, normalize ? w : plainText(w)) >= 0) ?? [])[1] ?? null;
  const date = todayISO ? extractDate(tokens, todayISO) : null;
  const time = extractTime(tokens);
  const kw = k => has(tokens, normalize ? KW[k] : KW[k].map(plainText));
  let intent = 'unknown';
  if (kw('human')) intent = 'human';
  else if (kw('cancel')) intent = 'cancel';
  else if (kw('book') || (service && (date || time !== null))) intent = 'book';
  else if (kw('price') && (service || !kw('hours'))) intent = 'price';
  else if (kw('hours') || ((date || time !== null) && /\b(open|مفتوح)/.test(norm))) intent = 'hours';
  else if (kw('location')) intent = 'location';
  else if (kw('services')) intent = 'services';
  else if (service) intent = 'price';
  else if (kw('thanks')) intent = 'thanks';
  else if (kw('greeting')) intent = 'greeting';
  return { intent, service, date, time, normalized: norm };
}

// ---- whatsapp.mjs
// WhatsApp Cloud API: reading webhooks and building send payloads, with the platform's limits enforced in code.
const LIMITS = { textBody: 4096, interactiveBody: 1024, buttons: 3, buttonTitle: 20, listRows: 10, rowTitle: 24, rowDescription: 72, listButton: 20, windowMs: 24 * 3600 * 1000 };

// One webhook POST can carry several messages and status updates. Only customer messages get an answer.
function parseWebhook(body) {
  const out = [];
  if (!body || body.object !== 'whatsapp_business_account') return out;
  for (const entry of body.entry ?? []) for (const change of entry.changes ?? []) {
    if (change.field !== 'messages') continue;
    const v = change.value ?? {};
    const phoneNumberId = v.metadata?.phone_number_id ?? null;
    const names = Object.fromEntries((v.contacts ?? []).map(c => [c.wa_id, c.profile?.name ?? null]));
    for (const m of v.messages ?? []) {
      const base = { kind: 'message', id: m.id, from: m.from, name: names[m.from] ?? null, timestampMs: Number(m.timestamp) * 1000, phoneNumberId, type: m.type };
      if (m.type === 'text') out.push({ ...base, text: m.text?.body ?? '' });
      else if (m.type === 'interactive') { const r = m.interactive?.button_reply ?? m.interactive?.list_reply ?? {}; out.push({ ...base, replyId: r.id ?? null, text: r.title ?? '' }); }
      else if (m.type === 'button') out.push({ ...base, replyId: m.button?.payload ?? null, text: m.button?.text ?? '' });
      else out.push({ ...base, unsupported: true, text: '' });
    }
    for (const s of v.statuses ?? []) out.push({ kind: 'status', id: s.id, status: s.status, recipient: s.recipient_id, phoneNumberId });
  }
  return out;
}

// Meta retries a notification until it gets a 200, and retries go to every subscribed app, so the same message can arrive twice.
// The store is a plain object so n8n can keep it in workflow static data between executions.
function seenBefore(store, id, nowMs, ttlMs = 3 * 24 * 3600 * 1000) {
  for (const [k, t] of Object.entries(store)) if (nowMs - t > ttlMs) delete store[k];
  if (Object.prototype.hasOwnProperty.call(store, id)) return true;
  store[id] = nowMs;
  return false;
}

const windowOpen = (lastInboundMs, atMs) => lastInboundMs != null && atMs - lastInboundMs < LIMITS.windowMs;

// A day-before reminder can go as a normal message only if the customer wrote within the 24 hours before it.
// Bookings less than a day away get no day-before reminder; one to two days away, a normal message; further ahead, a template.
function reminderPlan(appointmentMs, lastInboundMs, nowMs, leadMs = 24 * 3600 * 1000) {
  const sendAtMs = appointmentMs - leadMs;
  if (sendAtMs <= nowMs) return { sendAtMs: null, kind: 'none' };
  return { sendAtMs, kind: windowOpen(lastInboundMs, sendAtMs) ? 'service' : 'template' };
}

function splitText(body, max = LIMITS.textBody) {
  const parts = []; let rest = String(body);
  while (rest.length > max) {
    let cut = Math.max(rest.lastIndexOf('\n', max), rest.lastIndexOf('. ', max) + 1, rest.lastIndexOf(' ', max));
    if (cut <= 0) cut = max;
    parts.push(rest.slice(0, cut).trimEnd()); rest = rest.slice(cut).trimStart();
  }
  if (rest) parts.push(rest);
  return parts;
}

const base = to => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const textPayloads = (to, body) => splitText(body).map(t => ({ ...base(to), type: 'text', text: { preview_url: false, body: t } }));

function buttonsPayload(to, body, buttons, footer) {
  if (!buttons.length || buttons.length > LIMITS.buttons) throw new Error(`reply buttons: 1 to ${LIMITS.buttons}, got ${buttons.length}`);
  if (body.length > LIMITS.interactiveBody) throw new Error('interactive body over 1024 characters');
  const titles = new Set();
  for (const b of buttons) {
    if (!b.title || b.title.length > LIMITS.buttonTitle) throw new Error(`button title "${b.title}" must be 1-${LIMITS.buttonTitle} characters`);
    if (titles.has(b.title)) throw new Error('button titles must be unique'); titles.add(b.title);
    if (!b.id || b.id.length > 256 || b.id !== b.id.trim()) throw new Error('button id must be 1-256 characters with no outer spaces');
  }
  return { ...base(to), type: 'interactive', interactive: { type: 'button', body: { text: body }, ...(footer ? { footer: { text: footer } } : {}),
    action: { buttons: buttons.map(b => ({ type: 'reply', reply: { id: b.id, title: b.title } })) } } };
}

function listPayload(to, body, buttonText, rows, sectionTitle) {
  if (!rows.length || rows.length > LIMITS.listRows) throw new Error(`list rows: 1 to ${LIMITS.listRows}`);
  if (buttonText.length > LIMITS.listButton) throw new Error('list button text over 20 characters');
  for (const r of rows) if (r.title.length > LIMITS.rowTitle || (r.description ?? '').length > LIMITS.rowDescription) throw new Error(`list row "${r.title}" too long`);
  return { ...base(to), type: 'interactive', interactive: { type: 'list', body: { text: body }, action: { button: buttonText, sections: [{ title: sectionTitle.slice(0, 24), rows }] } } };
}

const templatePayload = (to, name, languageCode, params) => ({ ...base(to), type: 'template',
  template: { name, language: { code: languageCode }, components: [{ type: 'body', parameters: params.map(text => ({ type: 'text', text: String(text) })) }] } });

// ---- booking.mjs
// Free slots from the salon's hours, each stylist's skills and existing bookings. No double-booking.



const STEP = 15;
const overlaps = (a0, a1, b0, b1) => a0 < b1 && b0 < a1;

function freeStaff(serviceId, date, start, bookings, staff = SALON.staff) {
  const svc = serviceById(serviceId); if (!svc) return null;
  const end = start + svc.minutes;
  const hours = SALON.hours[dowOf(date)];
  if (!hours || start < hours[0] || end > hours[1]) return null;
  return staff.find(s => s.skills.includes(serviceId) && !bookings.some(b => b.staff === s.id && b.date === date && overlaps(start, end, b.start, b.end))) ?? null;
}

// Up to n slots at or after the wanted time; the wanted day first, then the next days.
function findSlots(serviceId, { nowMs, date = null, time = null, bookings = [], n = 3, days = 7 }) {
  const now = qatarParts(nowMs);
  const firstDay = date ?? now.date;
  const out = [];
  for (let k = 0; k < days && out.length < n; k++) {
    const d = addDaysISO(firstDay, k);
    if (d < now.date) continue;
    const hours = SALON.hours[dowOf(d)]; if (!hours) continue;
    let from = hours[0];
    if (k === 0 && time !== null) from = Math.max(from, time);
    if (d === now.date) from = Math.max(from, Math.ceil((now.minutes + 30) / STEP) * STEP); // at least 30 minutes' notice
    for (let t = Math.ceil(from / STEP) * STEP; t < hours[1] && out.length < n; t += STEP) {
      const s = freeStaff(serviceId, d, t, bookings);
      if (s) { out.push({ slot: localISO(d, t), staff: s.id }); t += 45; } // spread the offers out
    }
  }
  return out;
}

function book(serviceId, slotISO, bookings) {
  const { date, minutes } = parseLocal(slotISO);
  const s = freeStaff(serviceId, date, minutes, bookings);
  if (!s) return { ok: false, reason: 'taken' };
  const svc = serviceById(serviceId);
  const booking = { service: serviceId, date, start: minutes, end: minutes + svc.minutes, staff: s.id, slot: slotISO };
  bookings.push(booking);
  return { ok: true, booking };
}

