}
function qatarMs(date, minutes) { return Date.parse(`${date}T00:00:00Z`) + (minutes - QATAR_OFFSET_MIN) * 60000; }
function addDaysISO(date, n) { const d = new Date(`${date}T00:00:00Z`); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function dowOf(date) { return new Date(`${date}T00:00:00Z`).getUTCDay(); }
