// Phrase match on whole tokens, allowing Arabic prefixes (al-, wal-, bil-, li-, wa-, bi-) on the first token.
function findPhrase(tokens, phrase) {
  const p = phrase.split(' ');
  for (let i = 0; i + p.length <= tokens.length; i++) {
