const AM = ['am', 'a.m', 'morning', AR('ص'), AR('صباحا'), AR('الصبح'), AR('الصباح'), AR('صبح')];
const HOUR_WORDS = { [N('وحده')]: 1, [N('واحده')]: 1, [N('ثنتين')]: 2, [N('اثنين')]: 2, [N('ثلاث')]: 3, [N('ثلاثه')]: 3,
