    else if (plain) { h = +plain[1]; m = +(plain[2] ?? 0); }
    else if (HOUR_WORDS[t] && i > 0 && AT.some(a => variants(tokens[i - 1]).has(a.split(' ').at(-1)))) h = HOUR_WORDS[t];
    if (h === null || h > 23 || m > 59) continue;
